import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
export class Effects{constructor(scene){this.scene=scene;this.items=[];this.shake=0}burst(position,color=0xe4b84a,count=8){for(let i=0;i<count;i++){const mesh=new THREE.Mesh(new THREE.SphereGeometry(.012,5,5),new THREE.MeshBasicMaterial({color}));mesh.position.copy(position);mesh.userData.velocity=new THREE.Vector3((Math.random()-.5)*.8,Math.random()*.8,(Math.random()-.5)*.8);mesh.userData.life=.5;this.scene.add(mesh);this.items.push(mesh)}}tracer(start,end){const geometry=new THREE.BufferGeometry().setFromPoints([start,end]);const line=new THREE.Line(geometry,new THREE.LineBasicMaterial({color:0xffe08a,transparent:true}));this.scene.add(line);setTimeout(()=>{this.scene.remove(line);geometry.dispose()},90)}update(dt){for(let i=this.items.length-1;i>=0;i--){const item=this.items[i];item.userData.life-=dt;item.position.addScaledVector(item.userData.velocity,dt);item.userData.velocity.y-=1.6*dt;item.material.opacity=Math.max(0,item.userData.life*2);if(item.userData.life<=0){this.scene.remove(item);item.geometry.dispose();item.material.dispose();this.items.splice(i,1)}}if(this.shake>0)this.shake=Math.max(0,this.shake-dt*3)}screenShake(amount=.2){this.shake=Math.max(this.shake,amount);document.body.classList.remove('shake');void document.body.offsetWidth;document.body.classList.add('shake')}}
